import {published} from './content-schema.mjs';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=s=>e(s).replace(/\n/g,'<br>');
export function whatsapp(c,kind){const s=c.settings,number=s.whatsappCountryCode+s.whatsappNumber;if(!s.whatsappCountryCode||!s.whatsappNumber||!/^[1-9]\d{6,14}$/.test(number))return '';const message=kind==='application'?s.whatsappCandidateMessage:s.whatsappCustomerMessage;return `<a class="whatsapp-link" href="https://wa.me/${number}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">WhatsApp · ${kind==='application'?'Careers':'Service enquiries'} ↗</a>`;}
export function socials(c){const s=c.settings;return ['instagram','facebook','linkedin','tiktok','youtube','otherSocialUrl'].filter(key=>s[key]).map(key=>`<a class="social-link" href="${e(s[key])}" target="_blank" rel="noopener noreferrer" aria-label="${e(key==='otherSocialUrl'?s.otherSocialLabel||'Social profile':key)}">${e(key==='otherSocialUrl'?s.otherSocialLabel||'Social profile':key==='linkedin'?'LinkedIn':key==='tiktok'?'TikTok':key.charAt(0).toUpperCase()+key.slice(1))} ↗</a>`).join('');}
export function announcements(c){const rows=published(c.announcements);const banner=c.settings.bannerEnabled&&(c.settings.bannerText||c.settings.bannerImage)?`<section class="site-banner wrap">${c.settings.bannerImage?`<img src="${e(c.settings.bannerImage)}" alt="${e(c.settings.bannerImageAlt)}" loading="lazy" width="1200" height="320">`:''}${c.settings.bannerText?`<p>${e(c.settings.bannerText)}</p>`:''}</section>`:'';return banner+(rows.length?`<section class="announcements wrap"><p class="eyebrow">${e(c.settings.announcementHeading)}</p>${rows.map(a=>`<article><h3>${e(a.title)}</h3><p>${e(a.text)}</p>${a.url?`<a class="text-link" href="${e(a.url)}" target="_blank" rel="noopener noreferrer">Learn more ↗</a>`:''}</article>`).join('')}</section>`:'');}
export function testimonials(c){const rows=published(c.testimonials);return rows.length?`<section class="wrap section testimonials"><p class="eyebrow">${e(c.settings.testimonialHeading)}</p><div class="quote-grid">${rows.map(t=>`<figure><blockquote>${e(t.quote)}</blockquote><figcaption><strong>${e(t.client)}</strong>${t.role?`<span>${e(t.role)}</span>`:''}</figcaption></figure>`).join('')}</div></section>`:'';}
export function certifications(c){const rows=published(c.certifications);return rows.length?`<section class="wrap section credentials"><p class="eyebrow">${e(c.settings.certificationHeading)}</p><div class="credentials-grid">${rows.map(t=>`<article>${t.image?`<img src="${e(t.image)}" alt="${e(t.imageAlt)}" loading="lazy" width="240" height="180">`:''}<h3>${e(t.title)}</h3><p>${e(t.issuer)}</p><p>${e(t.description)}</p>${t.url?`<a class="text-link" href="${e(t.url)}" target="_blank" rel="noopener noreferrer">View credential ↗</a>`:''}</article>`).join('')}</div></section>`:'';}
export function projectCards(c){const rows=published(c.projects);return rows.length?`<div class="project-grid">${rows.map(p=>`<article>${p.image?`<img src="${e(p.image)}" alt="${e(p.imageAlt)}" loading="lazy" width="900" height="600">`:''}<div><p class="eyebrow">${e(p.location)}</p><h3>${e(p.title)}</h3><p>${e(p.description)}</p></div></article>`).join('')}</div>`:'';}
export function jobCards(c){const today=new Date().toISOString().slice(0,10),rows=published(c.jobs).filter(j=>!j.closing||j.closing>=today);return `<div class="jobs-list">${rows.length?rows.map(j=>`<article class="vacancy-row"><div><span class="job-meta">${e([j.location,j.type].filter(Boolean).join(' · '))}</span><h3>${e(j.title)}</h3><p>${lines(j.requirements)}</p>${j.closing?`<span class="field-help">Closing date: ${e(j.closing)}</span>`:''}</div><a class="button secondary" href="/careers.html?position=${encodeURIComponent(j.title)}#apply">${e(c.settings.candidateButton)} ↗</a></article>`).join(''):`<p class="vacancy-empty">${e(c.settings.jobsEmpty)}</p>`}</div>`;}
export function fieldHtml(field,name,type='text',options=null){if(!field.enabled)return '';const required=field.required?'required':'';return `<label>${e(field.label)}${field.required?' <span aria-hidden="true">*</span>':' <span class="optional">(optional)</span>'}${options?`<select name="${e(name)}" ${required}><option value="">Select an option</option>${options.map(x=>`<option>${e(x)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${e(name)}" rows="4" maxlength="4000" ${required}></textarea>`:`<input name="${e(name)}" type="${e(type)}" ${type==='number'?'min="0"':'maxlength="1000"'} ${required} ${name==='email'?'autocomplete="email"':name==='phone'?'autocomplete="tel"':name==='name'?'autocomplete="name"':''}>`}</label>`;}
